create function public.create_group(p_name text,p_currency text,p_kind text default 'friends',p_description text default '',p_icon text default '◈') returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid:=private.require_user(); g uuid; begin
 if (select count(*) from public.groups where owner_id=u and created_at>now()-interval '1 day')>=20 then raise exception 'Daily group limit reached'; end if;
 insert into public.groups(name,currency,kind,description,icon,owner_id) values(trim(p_name),p_currency,p_kind,p_description,p_icon,u) returning id into g;
 insert into public.group_members(group_id,user_id,role,billing_manager) values(g,u,'owner',true); perform private.audit(g,'group_created',g); return g;
end $$;
create function public.list_members(p_group uuid) returns table(user_id uuid,display_name text,role text,active boolean) language plpgsql security definer set search_path='' as $$ begin perform private.require_member(p_group); return query select m.user_id,p.display_name,m.role,m.active from public.group_members m join public.profiles p on p.id=m.user_id where m.group_id=p_group order by m.joined_at; end $$;
create function public.invite_member(p_group uuid,p_email text default null) returns text language plpgsql security definer set search_path='' as $$
declare token text:=replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-',''); begin
 perform private.require_open(p_group); if not private.is_manager(p_group) then raise exception 'Manager role required' using errcode='42501'; end if;
 if (select count(*) from public.group_invitations where invited_by=auth.uid() and created_at>now()-interval '1 hour')>=30 then raise exception 'Invitation rate limit'; end if;
 insert into public.group_invitations(group_id,token_hash,email,invited_by) values(p_group,encode(sha256(convert_to(token,'UTF8')),'hex'),nullif(lower(trim(p_email)),''),auth.uid());
 perform private.audit(p_group,'invitation_created',null); return token;
end $$;
create function public.accept_invitation(p_token text) returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid:=private.require_user(); inv public.group_invitations; verified boolean; mail text; begin
 select email_confirmed_at is not null, lower(email) into verified,mail from auth.users where id=u;
 if not coalesce(verified,false) then raise exception 'Verify your email before joining'; end if;
 select * into inv from public.group_invitations where token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex') for update;
 if inv.id is null or inv.expires_at<=now() or inv.accepted_by is not null then raise exception 'Invalid, expired, or used invitation'; end if;
 if inv.email is not null and inv.email<>mail then raise exception 'Invitation belongs to another email' using errcode='42501'; end if;
 perform 1 from public.groups where id=inv.group_id and archived_at is null for update;
 if not found then raise exception 'Group is archived'; end if;
 if (select count(*) from public.group_members where group_id=inv.group_id and active)>=100 then raise exception 'Group member limit reached'; end if;
 if exists(select 1 from public.group_members where group_id=inv.group_id and user_id=u and active) then raise exception 'Already a group member'; end if;
 insert into public.group_members(group_id,user_id) values(inv.group_id,u) on conflict(group_id,user_id) do update set active=true,role='member',billing_manager=false,left_at=null;
 update public.group_invitations set accepted_by=u,accepted_at=now() where id=inv.id; perform private.audit(inv.group_id,'member_joined',u); return inv.group_id;
end $$;
create function public.group_balances(p_group uuid) returns table(group_id uuid,user_id uuid,currency text,balance_minor bigint) language plpgsql security definer set search_path='' as $$ begin perform private.require_member(p_group); return query select l.group_id,l.user_id,l.currency,sum(l.delta_minor)::bigint from public.financial_ledger_entries l where l.group_id=p_group group by l.group_id,l.user_id,l.currency; end $$;

-- Serializes duplicate mutations before checking payload and returning the original result.
create function private.replay(p_key uuid,p_operation text,p_payload jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare r private.mutation_keys; begin
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||p_key::text,0));
 select * into r from private.mutation_keys where user_id=auth.uid() and idempotency_key=p_key;
 if found then if r.operation<>p_operation or r.payload_hash<>encode(sha256(convert_to(p_payload::text,'UTF8')),'hex') then raise exception 'Idempotency key reused with a different payload'; end if; return r.result_id; end if; return null;
end $$;
create function private.remember(p_key uuid,p_operation text,p_payload jsonb,p_result uuid) returns void language sql security definer set search_path='' as $$ insert into private.mutation_keys(user_id,idempotency_key,operation,payload_hash,result_id) values(auth.uid(),p_key,p_operation,encode(sha256(convert_to(p_payload::text,'UTF8')),'hex'),p_result) $$;

-- Defined here with no premium access; replaced by the entitlement migration.
create function public.has_group_feature(p_user uuid,p_group uuid,p_feature text) returns boolean language sql stable security definer set search_path='' as $$ select false $$;

create function private.reverse_expense(p_expense uuid,p_version int) returns uuid language plpgsql security definer set search_path='' as $$
declare e public.expenses; begin
 select * into e from public.expenses where id=p_expense for update; perform private.require_open(e.group_id);
 if e.created_by<>auth.uid() and not private.is_manager(e.group_id) then raise exception 'Expense author or manager required' using errcode='42501'; end if;
 if e.version<>p_version or e.reversed_at is not null then raise exception 'Expense changed. Refresh before trying again' using errcode='40001'; end if;
 insert into public.financial_ledger_entries(group_id,user_id,currency,delta_minor,expense_id,entry_type) select group_id,user_id,currency,-delta_minor,expense_id,'expense_reversal' from public.financial_ledger_entries where expense_id=p_expense and entry_type='expense';
 update public.expenses set reversed_at=now(),version=version+1,updated_at=now() where id=p_expense; perform private.audit(e.group_id,'expense_reversed',p_expense); return p_expense;
end $$;
create function public.reverse_expense(p_expense uuid,p_version int,p_key uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare prior uuid; payload jsonb:=jsonb_build_object('id',p_expense,'v',p_version); begin perform private.require_user(); prior:=private.replay(p_key,'reverse',payload); if prior is not null then return prior; end if; prior:=private.reverse_expense(p_expense,p_version); perform private.remember(p_key,'reverse',payload,prior); return prior; end $$;

create function public.create_expense(p jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid:=private.require_user(); g uuid:=(p->>'group_id')::uuid; total bigint:=(p->>'amount_minor')::bigint;
 curr text:=p->>'currency'; method text:=p->>'split_method'; participants jsonb:=p->'participants'; n int; denom numeric; funded numeric; e uuid; prior uuid; row record; key uuid:=(p->>'idempotency_key')::uuid;
begin
 perform private.require_open(g); if key is null then raise exception 'Idempotency key required'; end if;
 prior:=private.replay(key,'expense',p); if prior is not null then return prior; end if;
 perform 1 from public.groups where id=g for update;
 perform private.require_open(g);
 if total is null or total<1 or total>999999999999 then raise exception 'Invalid total'; end if;
 if curr is null or curr not in ('INR','USD','EUR','GBP','JPY','KWD') then raise exception 'Unsupported currency'; end if;
 if jsonb_typeof(participants)<>'array' or jsonb_typeof(p->'payers')<>'array' then raise exception 'Participants and payers required'; end if;
 if method='itemized' then participants:=private.itemized_shares(total,p->'items'); end if;
 n:=jsonb_array_length(participants);
 if n<1 or n>100 or jsonb_array_length(p->'payers') not between 1 and 100 then raise exception 'Invalid participant count'; end if;
 if (select count(distinct x->>'user_id') from jsonb_array_elements(participants) x)<>n then raise exception 'Duplicate participants'; end if;
 if (select count(distinct x->>'user_id') from jsonb_array_elements(p->'payers') x)<>jsonb_array_length(p->'payers') then raise exception 'Duplicate payers'; end if;
 for row in select x->>'user_id' uid,x->>'value' val from jsonb_array_elements(participants) x loop
  if not exists(select 1 from public.group_members where group_id=g and user_id=row.uid::uuid and active) then raise exception 'Participant is not an active member'; end if;
  if method<>'equal' and (row.val is null or row.val !~ '^\d+$' or row.val::numeric>999999999999) then raise exception 'Invalid split value'; end if;
 end loop;
 for row in select x->>'user_id' uid,x->>'amount_minor' val from jsonb_array_elements(p->'payers') x loop
  if not exists(select 1 from public.group_members where group_id=g and user_id=row.uid::uuid and active) then raise exception 'Payer is not an active member'; end if;
  if row.val is null or row.val !~ '^\d+$' or row.val::numeric>999999999999 then raise exception 'Invalid payer amount'; end if;
 end loop;
 select sum((x->>'amount_minor')::numeric) into funded from jsonb_array_elements(p->'payers') x;
 if funded<>total then raise exception 'Payers must fund the total'; end if;
 select sum(case when method='equal' then 1 else (x->>'value')::numeric end) into denom from jsonb_array_elements(participants) x;
 if method in ('exact','custom','itemized') and denom<>total then raise exception 'Shares must equal total'; end if;
 if method='percentage' and denom<>10000 then raise exception 'Percentages must total 10000 basis points'; end if;
 if denom<=0 then raise exception 'Positive weights required'; end if;
 if method='itemized' and not public.has_group_feature(u,g,'itemized') then raise exception 'Group Plus required' using errcode='42501'; end if;
 if p->>'replaces_id' is not null then
  if not exists(select 1 from public.expenses where id=(p->>'replaces_id')::uuid and group_id=g) then raise exception 'Correction group mismatch'; end if;
  if p->>'expected_version' is null then raise exception 'Expected version required'; end if;
  perform private.reverse_expense((p->>'replaces_id')::uuid,(p->>'expected_version')::int);
 end if;
 if (select count(*) from public.expenses where created_by=u and created_at>now()-interval '1 hour')>=300 then raise exception 'Expense rate limit'; end if;
 insert into public.expenses(group_id,created_by,description,amount_minor,currency,category,split_method,expense_date,notes,replaces_id)
 values(g,u,trim(p->>'description'),total,curr,p->>'category',method,(p->>'expense_date')::date,coalesce(p->>'notes',''),(p->>'replaces_id')::uuid) returning id into e;
 insert into public.expense_payers select e,g,(x->>'user_id')::uuid,(x->>'amount_minor')::bigint from jsonb_array_elements(p->'payers') x;
 if method='itemized' then insert into public.expense_items(expense_id,group_id,description,amount_minor,allocations) select e,g,x->>'description',(x->>'amount_minor')::bigint,x->'allocations' from jsonb_array_elements(p->'items') x; end if;
 insert into public.expense_participants select e,g,(x->>'user_id')::uuid from jsonb_array_elements(participants) x;
 if method in ('exact','custom','itemized') then
  insert into public.expense_splits select e,g,(x->>'user_id')::uuid,(x->>'value')::bigint,(x->>'value')::bigint from jsonb_array_elements(participants) x;
 else
  -- NUMERIC multiplication avoids bigint overflow. No floating point is involved.
  insert into public.expense_splits(expense_id,group_id,user_id,amount_minor,input_value)
  with inputs as (select (x->>'user_id')::uuid uid,case when method='equal' then 1 else (x->>'value')::numeric end weight from jsonb_array_elements(participants) x),
  base as (select uid,weight,floor(total::numeric*weight/denom) amount,mod(total::numeric*weight,denom) rem from inputs),
  ranked as (select *,row_number() over(order by rem desc,uid) rank,total-sum(amount) over() leftover from base)
  select e,g,uid,(amount+case when rank<=leftover then 1 else 0 end)::bigint,weight::bigint from ranked;
 end if;
 insert into public.financial_ledger_entries(group_id,user_id,currency,delta_minor,expense_id,entry_type)
 select g,uid,curr,sum(delta)::bigint,e,'expense' from (select user_id uid,amount_minor delta from public.expense_payers where expense_id=e union all select user_id,-amount_minor from public.expense_splits where expense_id=e) x group by uid;
 if (select sum(delta_minor) from public.financial_ledger_entries where expense_id=e)<>0 then raise exception 'Ledger must balance'; end if;
 perform private.audit(g,case when p->>'replaces_id' is null then 'expense_added' else 'expense_corrected' end,e,jsonb_build_object('description',p->>'description','currency',curr,'amount_minor',total));
 insert into public.notifications(user_id,group_id,kind) select user_id,g,'expense_added' from public.group_members where group_id=g and active and user_id<>u;
 perform private.remember(key,'expense',p,e); return e;
end $$;

create function public.create_settlement(p jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid:=private.require_user(); g uuid:=(p->>'group_id')::uuid; f uuid:=(p->>'from_user')::uuid; t uuid:=(p->>'to_user')::uuid; s uuid; prior uuid; k uuid:=(p->>'idempotency_key')::uuid; begin
 perform private.require_open(g); if k is null then raise exception 'Idempotency key required'; end if; prior:=private.replay(k,'settlement',p); if prior is not null then return prior; end if;
 if u<>f and u<>t then raise exception 'Only payment parties can record a settlement' using errcode='42501'; end if;
 if not exists(select 1 from public.group_members where group_id=g and user_id=f) or not exists(select 1 from public.group_members where group_id=g and user_id=t) then raise exception 'Payment parties must belong to group'; end if;
 insert into public.settlements(group_id,from_user,to_user,amount_minor,currency,method,notes,payment_reference,created_by) values(g,f,t,(p->>'amount_minor')::bigint,p->>'currency',p->>'method',coalesce(p->>'notes',''),coalesce(p->>'payment_reference',''),u) returning id into s;
 perform private.audit(g,'settlement_requested',s); perform private.remember(k,'settlement',p,s); return s;
end $$;
create function public.respond_settlement(p_id uuid,p_action text) returns void language plpgsql security definer set search_path='' as $$
declare s public.settlements; u uuid:=private.require_user(); begin
 select * into s from public.settlements where id=p_id for update; perform private.require_open(s.group_id);
 if u<>s.from_user and u<>s.to_user then raise exception 'Only payment parties may respond' using errcode='42501'; end if;
 if p_action='confirm' then
  if s.status='confirmed' then return; end if;
  if u=s.created_by then raise exception 'The other payment party must confirm'; end if;
  if s.status<>'pending' then raise exception 'Settlement is not pending'; end if;
  insert into public.settlement_confirmations(settlement_id,group_id,confirmed_by) values(s.id,s.group_id,u);
  insert into public.financial_ledger_entries(group_id,user_id,currency,delta_minor,settlement_id,entry_type) values(s.group_id,s.from_user,s.currency,s.amount_minor,s.id,'settlement'),(s.group_id,s.to_user,s.currency,-s.amount_minor,s.id,'settlement');
  update public.settlements set status='confirmed' where id=s.id;
 elsif p_action='dispute' then
  if s.status<>'pending' then raise exception 'Only pending payments may be disputed'; end if; update public.settlements set status='disputed' where id=s.id;
 elsif p_action='reverse' then
  if s.status='reversed' then return; end if;
  if s.status<>'confirmed' then raise exception 'Only confirmed settlements may be reversed'; end if;
  insert into public.financial_ledger_entries(group_id,user_id,currency,delta_minor,settlement_id,entry_type) select group_id,user_id,currency,-delta_minor,settlement_id,'settlement_reversal' from public.financial_ledger_entries where settlement_id=s.id and entry_type='settlement';
  update public.settlements set status='reversed' where id=s.id;
 else raise exception 'Unknown action'; end if;
 perform private.audit(s.group_id,'settlement_'||p_action,s.id);
end $$;

create function public.manage_member(p_group uuid,p_user uuid,p_action text) returns void language plpgsql security definer set search_path='' as $$
declare u uuid:=private.require_user(); owner uuid; begin
 perform private.require_open(p_group); select owner_id into owner from public.groups where id=p_group for update;
 if p_action='leave' then
  if p_user<>u then raise exception 'Cannot leave for another member'; end if;
 elsif owner<>u then raise exception 'Owner required' using errcode='42501'; end if;
 if p_action in ('remove','leave') then
  if p_user=owner then raise exception 'Transfer ownership before leaving'; end if;
  if exists(select 1 from public.financial_ledger_entries where group_id=p_group and user_id=p_user group by currency having sum(delta_minor)<>0) then raise exception 'Settle outstanding balances before leaving'; end if;
  update public.group_members set active=false,left_at=now(),billing_manager=false where group_id=p_group and user_id=p_user;
 elsif p_action='transfer' then
  if p_user=u or not exists(select 1 from public.group_members where group_id=p_group and user_id=p_user and active) then raise exception 'Choose another active member'; end if;
  update public.group_members set role='admin' where group_id=p_group and user_id=u;
  update public.group_members set role='owner' where group_id=p_group and user_id=p_user;
  update public.groups set owner_id=p_user,updated_at=now() where id=p_group;
 elsif p_action in ('admin','member') then update public.group_members set role=p_action where group_id=p_group and user_id=p_user and user_id<>owner and active;
 elsif p_action='billing_manager' then update public.group_members set billing_manager=not billing_manager where group_id=p_group and user_id=p_user and active;
 else raise exception 'Unknown action'; end if; perform private.audit(p_group,'member_'||p_action,p_user);
end $$;
create function public.archive_group(p_group uuid) returns void language plpgsql security definer set search_path='' as $$ begin perform private.require_open(p_group); if not exists(select 1 from public.groups where id=p_group and owner_id=auth.uid()) then raise exception 'Owner required'; end if; update public.groups set archived_at=now() where id=p_group; perform private.audit(p_group,'group_archived',p_group); end $$;
create function public.add_comment(p_expense uuid,p_body text) returns uuid language plpgsql security definer set search_path='' as $$ declare g uuid; c uuid; begin select group_id into g from public.expenses where id=p_expense; perform private.require_open(g); insert into public.expense_comments(expense_id,group_id,user_id,body) values(p_expense,g,auth.uid(),trim(p_body)) returning id into c; perform private.audit(g,'comment_added',p_expense); return c; end $$;
create function public.request_account_deletion() returns void language plpgsql security definer set search_path='' as $$ begin perform private.require_user(); if exists(select 1 from public.groups where owner_id=auth.uid() and archived_at is null) then raise exception 'Transfer or archive owned groups first'; end if; update public.user_preferences set deletion_requested_at=now() where user_id=auth.uid(); insert into public.audit_logs(actor_id,action) values(auth.uid(),'account_deletion_requested'); end $$;

-- Remove PostgreSQL's default PUBLIC execution privilege. Grant only explicit API surface.
revoke execute on all functions in schema public from public,anon,authenticated;
revoke execute on all functions in schema private from public,anon,authenticated;
grant execute on function public.is_group_member(uuid),public.has_group_feature(uuid,uuid,text),public.create_group(text,text,text,text,text),public.list_members(uuid),public.invite_member(uuid,text),public.accept_invitation(text),public.group_balances(uuid),public.create_expense(jsonb),public.reverse_expense(uuid,int,uuid),public.create_settlement(jsonb),public.respond_settlement(uuid,text),public.manage_member(uuid,uuid,text),public.archive_group(uuid),public.add_comment(uuid,text),public.request_account_deletion() to authenticated;


-- 202610270002_premium.sql
create table public.billing_customers (user_id uuid primary key references public.profiles, revenuecat_id text unique not null, created_at timestamptz not null default now());
create table public.billing_purchase_intents (id uuid primary key default gen_random_uuid(), purchaser_id uuid not null references public.profiles, group_id uuid not null references public.groups, product_id text not null, expires_at timestamptz not null default now()+interval '1 hour', consumed_at timestamptz, created_at timestamptz not null default now());
create unique index one_pending_purchase on public.billing_purchase_intents(purchaser_id) where consumed_at is null;
create table public.billing_purchases (id uuid primary key default gen_random_uuid(), purchaser_id uuid not null references public.profiles, group_id uuid not null references public.groups, provider text not null check(provider in ('APP_STORE','PLAY_STORE','STRIPE')), original_transaction_id text not null, product_id text not null, status text not null check(status in ('active','grace','cancelled','expired','revoked')), current_period_start timestamptz not null, current_period_end timestamptz not null, renews boolean not null, last_event_ms bigint not null default 0, created_at timestamptz not null default now(), unique(provider,original_transaction_id));
-- First release: one immutable beneficiary per purchaser, including after expiration.
-- This fails closed on store ownership ambiguity; a future migration may add vetted slots.
create unique index one_store_slot_per_payer on public.billing_purchases(purchaser_id);
create table public.group_subscription_entitlements (group_id uuid primary key references public.groups, purchase_id uuid unique not null references public.billing_purchases, purchaser_id uuid not null references public.profiles, status text not null check(status in ('active','grace','cancelled','expired','revoked')), expires_at timestamptz not null, renews boolean not null, updated_at timestamptz not null default now());
create table public.billing_events (id text primary key, provider text not null, event_type text not null, event_timestamp_ms bigint not null, purchase_id uuid references public.billing_purchases, disposition text not null, created_at timestamptz not null default now());
create trigger billing_events_immutable before update or delete on public.billing_events for each row execute function private.immutable();
create table public.premium_feature_usage (group_id uuid not null references public.groups, feature_key text not null, period date not null, used int not null default 0 check(used>=0), primary key(group_id,feature_key,period));
create table public.group_feature_settings (group_id uuid not null references public.groups, feature_key text not null, enabled boolean not null default true, primary key(group_id,feature_key));
create table public.budgets (id uuid primary key default gen_random_uuid(), group_id uuid not null references public.groups, month date not null check(extract(day from month)=1), currency text not null check(currency in ('INR','USD','EUR','GBP','JPY','KWD')), amount_minor bigint not null check(amount_minor between 1 and 999999999999), alert_percent int not null default 80 check(alert_percent between 1 and 100), created_by uuid not null references public.profiles, created_at timestamptz not null default now(), unique(group_id,month,currency));
create table public.budget_categories (id uuid primary key default gen_random_uuid(), budget_id uuid not null references public.budgets, group_id uuid not null references public.groups, category text not null, amount_minor bigint not null check(amount_minor>0), unique(budget_id,category));
create table public.recurring_expenses (id uuid primary key default gen_random_uuid(), group_id uuid not null references public.groups, created_by uuid not null references public.profiles, template jsonb not null, next_date date not null, end_date date, interval_months int not null default 1 check(interval_months between 1 and 12), auto_post boolean not null default false, active boolean not null default true, created_at timestamptz not null default now());
create table public.recurring_expense_runs (id uuid primary key default gen_random_uuid(), group_id uuid not null references public.groups, recurring_id uuid not null references public.recurring_expenses, scheduled_date date not null, expense_id uuid references public.expenses, status text not null default 'awaiting_approval', unique(recurring_id,scheduled_date));
create table public.custom_split_rules (id uuid primary key default gen_random_uuid(), group_id uuid not null references public.groups, name text not null check(length(name) between 1 and 80), split_method text not null check(split_method in ('equal','percentage','weighted','exact','custom')), participants jsonb not null, created_by uuid not null references public.profiles, created_at timestamptz not null default now());
create table public.exchange_rates (id uuid primary key default gen_random_uuid(), base_currency text not null, quote_currency text not null, numerator bigint not null check(numerator>0), denominator bigint not null check(denominator>0), source text not null, effective_at timestamptz not null, unique(base_currency,quote_currency,effective_at));
create table public.product_flags (key text primary key, enabled boolean not null default false);
insert into public.product_flags values('receipt_scan',false),('assistant',false),('trip_mode',false),('personal_expenses',false);
do $$ declare t text; begin foreach t in array array['billing_customers','billing_purchase_intents','billing_purchases','group_subscription_entitlements','billing_events','premium_feature_usage','group_feature_settings','budgets','budget_categories','recurring_expenses','recurring_expense_runs','custom_split_rules','exchange_rates','product_flags'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
do $$ declare t text; begin foreach t in array array['group_subscription_entitlements','premium_feature_usage','group_feature_settings','budgets','budget_categories','recurring_expenses','recurring_expense_runs','custom_split_rules'] loop execute format('create policy member_read on public.%I for select to authenticated using(public.is_group_member(group_id))',t); end loop; end $$;
create policy customer_read on public.billing_customers for select to authenticated using(user_id=auth.uid());
create policy purchase_read on public.billing_purchases for select to authenticated using(purchaser_id=auth.uid());
create policy intent_read on public.billing_purchase_intents for select to authenticated using(purchaser_id=auth.uid());
create policy flags_read on public.product_flags for select to authenticated using(true);
grant select on all tables in schema public to authenticated;
grant all on all tables in schema public to service_role;
grant all on all tables in schema private to service_role;

create or replace function public.has_group_feature(p_user uuid,p_group uuid,p_feature text) returns boolean language sql stable security definer set search_path='' as $$
 select p_user=auth.uid() and public.is_group_member(p_group)
 and p_feature in ('itemized','budgets','analytics','settlement_plan','recurring','reports','custom_rules')
 and exists(select 1 from public.group_subscription_entitlements where group_id=p_group and status in ('active','grace','cancelled') and expires_at>now())
 and not exists(select 1 from public.group_feature_settings where group_id=p_group and feature_key=p_feature and not enabled)
$$;

create function public.begin_group_purchase(p_group uuid,p_product text) returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid:=private.require_user(); i uuid; begin
 perform private.require_open(p_group); perform pg_advisory_xact_lock(hashtextextended(u::text,1));
 if not exists(select 1 from public.group_members where group_id=p_group and user_id=u and active and billing_manager) then raise exception 'Billing manager role required' using errcode='42501'; end if;
 if exists(select 1 from public.billing_purchases where purchaser_id=u and group_id<>p_group) then raise exception 'Your store subscription is already assigned to another group'; end if;
 if exists(select 1 from public.group_subscription_entitlements where group_id=p_group and expires_at>now() and status in ('active','grace','cancelled')) then raise exception 'This group already has an active subscription'; end if;
 if p_product not in ('tracksy_group_monthly','tracksy_group_yearly') then raise exception 'Unknown product'; end if;
 update public.billing_purchase_intents set consumed_at=now() where purchaser_id=u and consumed_at is null and expires_at<=now();
 select id into i from public.billing_purchase_intents where purchaser_id=u and consumed_at is null and group_id=p_group and product_id=p_product;
 if i is not null then return i; end if;
 if exists(select 1 from public.billing_purchase_intents where purchaser_id=u and consumed_at is null) then raise exception 'Another purchase is in progress'; end if;
 insert into public.billing_customers(user_id,revenuecat_id) values(u,u::text) on conflict do nothing;
 insert into public.billing_purchase_intents(purchaser_id,group_id,product_id) values(u,p_group,p_product) returning id into i; return i;
end $$;

-- SERVICE ROLE ONLY. Edge function verifies webhook authentication and fetches RevenueCat's
-- current server-side subscriber state before calling this transaction.
create function public.apply_verified_billing(p jsonb) returns text language plpgsql security definer set search_path='' as $$
declare u uuid:=(p->>'user_id')::uuid; b public.billing_purchases; intent public.billing_purchase_intents; groupid uuid; result text; stamp bigint:=(p->>'event_timestamp_ms')::bigint; begin
 if auth.role()<>'service_role' then raise exception 'Service role required' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,1));
 if exists(select 1 from public.billing_events where id=p->>'event_id') then return 'duplicate'; end if;
 select * into b from public.billing_purchases where provider=p->>'provider' and original_transaction_id=p->>'original_transaction_id' for update;
 if b.id is not null and b.purchaser_id<>u then raise exception 'Purchase belongs to another account'; end if;
 if b.id is null then
  select * into intent from public.billing_purchase_intents where purchaser_id=u and consumed_at is null and expires_at>now() and product_id=p->>'product_id' for update;
  if intent.id is null then raise exception 'No authorized purchase intent'; end if;
  groupid:=intent.group_id; perform 1 from public.groups where id=groupid for update;
  if not exists(select 1 from public.group_members where group_id=groupid and user_id=u and active and billing_manager) then raise exception 'Purchase authorization changed'; end if;
  if exists(select 1 from public.group_subscription_entitlements where group_id=groupid and expires_at>now() and status in ('active','grace','cancelled')) then raise exception 'Group already subscribed'; end if;
  insert into public.billing_purchases(purchaser_id,group_id,provider,original_transaction_id,product_id,status,current_period_start,current_period_end,renews,last_event_ms)
  values(u,groupid,p->>'provider',p->>'original_transaction_id',p->>'product_id',p->>'status',(p->>'starts_at')::timestamptz,(p->>'expires_at')::timestamptz,(p->>'renews')::boolean,stamp) returning * into b;
  update public.billing_purchase_intents set consumed_at=now() where id=intent.id; result:='applied';
 elsif stamp<=b.last_event_ms then result:='stale';
 else
  update public.billing_purchases set status=p->>'status',current_period_start=(p->>'starts_at')::timestamptz,current_period_end=(p->>'expires_at')::timestamptz,renews=(p->>'renews')::boolean,last_event_ms=stamp,product_id=p->>'product_id' where id=b.id returning * into b; result:='applied';
 end if;
 if result='applied' then
  insert into public.group_subscription_entitlements(group_id,purchase_id,purchaser_id,status,expires_at,renews) values(b.group_id,b.id,u,b.status,b.current_period_end,b.renews)
  on conflict(group_id) do update set purchase_id=excluded.purchase_id,purchaser_id=excluded.purchaser_id,status=excluded.status,expires_at=excluded.expires_at,renews=excluded.renews,updated_at=now();
 end if;
 insert into public.billing_events(id,provider,event_type,event_timestamp_ms,purchase_id,disposition) values(p->>'event_id',p->>'provider',p->>'event_type',stamp,b.id,result); return result;
end $$;

create function public.set_budget(p_group uuid,p_month date,p_currency text,p_amount bigint) returns uuid language plpgsql security definer set search_path='' as $$ declare b uuid; begin
 perform private.require_open(p_group); if not private.is_manager(p_group) or not public.has_group_feature(auth.uid(),p_group,'budgets') then raise exception 'Group Plus and manager role required' using errcode='42501'; end if;
 insert into public.budgets(group_id,month,currency,amount_minor,created_by) values(p_group,p_month,p_currency,p_amount,auth.uid()) on conflict(group_id,month,currency) do update set amount_minor=excluded.amount_minor returning id into b; perform private.audit(p_group,'budget_updated',b); return b;
end $$;
create function public.group_analytics(p_group uuid,p_start date,p_end date) returns jsonb language plpgsql security definer set search_path='' as $$ declare result jsonb; begin
 perform private.require_member(p_group); if p_end<p_start or p_end-p_start>366 then raise exception 'Select a date range within one year'; end if;
 if not public.has_group_feature(auth.uid(),p_group,'analytics') then raise exception 'Group Plus required' using errcode='42501'; end if;
 select coalesce(jsonb_agg(x),'[]') into result from (select currency,category,date_trunc('month',expense_date)::date as month,sum(amount_minor)::bigint amount_minor,count(*) count from public.expenses where group_id=p_group and reversed_at is null and expense_date between p_start and p_end group by currency,category,date_trunc('month',expense_date)) x; return result;
end $$;
create function public.export_group(p_group uuid,p_start date,p_end date) returns jsonb language plpgsql security definer set search_path='' as $$ declare result jsonb; begin
 perform private.require_member(p_group); if p_end<p_start or p_end-p_start>366 then raise exception 'Select up to one year'; end if;
 select coalesce(jsonb_agg(x),'[]') into result from (select id,description,amount_minor,currency,category,expense_date,reversed_at,created_by from public.expenses where group_id=p_group and expense_date between p_start and p_end order by expense_date,id limit 10000) x; return result;
end $$;
create function public.save_split_rule(p_group uuid,p_name text,p_method text,p_participants jsonb) returns uuid language plpgsql security definer set search_path='' as $$ declare r uuid; begin
 perform private.require_open(p_group); if not private.is_manager(p_group) or not public.has_group_feature(auth.uid(),p_group,'custom_rules') then raise exception 'Group Plus and manager required'; end if;
 if jsonb_typeof(p_participants)<>'array' or jsonb_array_length(p_participants) not between 1 and 100 then raise exception 'Participants required'; end if;
 insert into public.custom_split_rules(group_id,name,split_method,participants,created_by) values(p_group,trim(p_name),p_method,p_participants,auth.uid()) returning id into r; return r;
end $$;

-- Admin console is limited to aggregate metadata. Never exposes expense rows.
create function public.admin_metrics() returns jsonb language plpgsql security definer set search_path='' as $$ begin
 if coalesce(auth.jwt()->'app_metadata'->>'role','')<>'admin' or coalesce(auth.jwt()->>'aal','')<>'aal2' then raise exception 'Admin role and MFA required' using errcode='42501'; end if;
 insert into public.audit_logs(actor_id,action) values(auth.uid(),'admin_metrics_viewed');
 return jsonb_build_object('users',(select count(*) from public.profiles),'groups',(select count(*) from public.groups),'active_premium_groups',(select count(*) from public.group_subscription_entitlements where expires_at>now() and status in ('active','grace','cancelled')),'open_support_requests',(select count(*) from public.support_requests where status='open'),'billing_events',(select count(*) from public.billing_events));
end $$;
revoke execute on function public.begin_group_purchase(uuid,text),public.apply_verified_billing(jsonb),public.set_budget(uuid,date,text,bigint),public.group_analytics(uuid,date,date),public.export_group(uuid,date,date),public.save_split_rule(uuid,text,text,jsonb),public.admin_metrics() from public,anon,authenticated;
grant execute on function public.begin_group_purchase(uuid,text),public.set_budget(uuid,date,text,bigint),public.group_analytics(uuid,date,date),public.export_group(uuid,date,date),public.save_split_rule(uuid,text,text,jsonb),public.admin_metrics() to authenticated;
grant execute on function public.apply_verified_billing(jsonb) to service_role;


-- 202610270003_storage.sql
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('receipts','receipts',false,10485760,array['image/jpeg','image/png','image/webp','application/pdf']),('avatars','avatars',false,2097152,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
-- Object names: <group uuid>/<uploader uuid>/<random uuid>.<extension>.
create policy receipt_read on storage.objects for select to authenticated using(bucket_id='receipts' and public.is_group_member(((storage.foldername(name))[1])::uuid));
create policy receipt_upload on storage.objects for insert to authenticated with check(bucket_id='receipts' and public.is_group_member(((storage.foldername(name))[1])::uuid) and (storage.foldername(name))[2]=auth.uid()::text);
create policy avatar_read on storage.objects for select to authenticated using(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text);
create policy avatar_upload on storage.objects for insert to authenticated with check(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text);
-- Subscribe only to tables with member-based RLS. Ledger mutations trigger client invalidation.
alter publication supabase_realtime add table public.expenses,public.settlements,public.group_members,public.group_subscription_entitlements;


-- 202610270004_operations.sql
create function public.update_group(p_group uuid,p_name text,p_description text) returns void language plpgsql security definer set search_path='' as $$ begin
 perform private.require_open(p_group); if not private.is_manager(p_group) then raise exception 'Manager required' using errcode='42501'; end if;
 update public.groups set name=trim(p_name),description=p_description,updated_at=now() where id=p_group; perform private.audit(p_group,'group_updated',p_group);
end $$;
create function public.attach_receipt(p_expense uuid,p_path text) returns uuid language plpgsql security definer set search_path='' as $$ declare g uuid; a uuid; begin
 select group_id into g from public.expenses where id=p_expense; perform private.require_open(g);
 if split_part(p_path,'/',1)<>g::text or split_part(p_path,'/',2)<>auth.uid()::text then raise exception 'Invalid receipt path'; end if;
 if not exists(select 1 from storage.objects where bucket_id='receipts' and name=p_path) then raise exception 'Upload the receipt first'; end if;
 insert into public.expense_attachments(expense_id,group_id,storage_path,uploaded_by) values(p_expense,g,p_path,auth.uid()) returning id into a;
 perform private.audit(g,'receipt_attached',p_expense); return a;
end $$;
create function public.group_report(p_group uuid,p_start date,p_end date) returns jsonb language plpgsql security definer set search_path='' as $$ begin
 perform private.require_member(p_group); if not public.has_group_feature(auth.uid(),p_group,'reports') then raise exception 'Group Plus required' using errcode='42501'; end if;
 return jsonb_build_object('expenses',public.export_group(p_group,p_start,p_end),'analytics',public.group_analytics(p_group,p_start,p_end),'balances',(select coalesce(jsonb_agg(b),'[]') from public.group_balances(p_group) b),'generated_at',now(),'start',p_start,'end',p_end);
end $$;

create table private.push_deliveries (notification_id uuid not null references public.notifications, device_id uuid not null references public.user_devices, attempts int not null default 0, claimed_at timestamptz, delivered_at timestamptz, next_attempt_at timestamptz not null default now(), ticket_id text, last_error text, primary key(notification_id,device_id));
create function public.claim_push_batch() returns jsonb language plpgsql security definer set search_path='' as $$ declare result jsonb; begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'Service role required'; end if;
 insert into private.push_deliveries(notification_id,device_id)
 select n.id,d.id from public.notifications n join public.user_devices d on d.user_id=n.user_id join public.notification_preferences p on p.user_id=n.user_id
 where n.created_at>now()-interval '1 day' and (n.kind='expense_added' and p.expenses or n.kind like 'settlement_%' and p.settlements) on conflict do nothing;
 with claimed as (
  select pd.notification_id,pd.device_id from private.push_deliveries pd join public.notifications n on n.id=pd.notification_id join public.user_preferences p on p.user_id=n.user_id
  where pd.delivered_at is null and pd.attempts<5 and pd.next_attempt_at<=now() and (pd.claimed_at is null or pd.claimed_at<now()-interval '5 minutes')
  -- Quiet hours are evaluated in the account’s configured IANA timezone.
  and (p.quiet_start is null or p.quiet_end is null or not(case when p.quiet_start>p.quiet_end then (now() at time zone p.timezone)::time>=p.quiet_start or (now() at time zone p.timezone)::time<p.quiet_end else (now() at time zone p.timezone)::time>=p.quiet_start and (now() at time zone p.timezone)::time<p.quiet_end end))
  order by pd.next_attempt_at limit 50 for update of pd skip locked
 ), updated as (update private.push_deliveries pd set claimed_at=now(),attempts=attempts+1 from claimed c where pd.notification_id=c.notification_id and pd.device_id=c.device_id returning pd.*)
 select coalesce(jsonb_agg(jsonb_build_object('notification_id',u.notification_id,'device_id',u.device_id,'token',d.push_token,'kind',n.kind,'group_id',n.group_id)),'[]') into result from updated u join public.user_devices d on d.id=u.device_id join public.notifications n on n.id=u.notification_id;
 return result;
end $$;
create function public.complete_push(p_notification uuid,p_device uuid,p_ticket text,p_error text) returns void language plpgsql security definer set search_path='' as $$ begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'Service role required'; end if;
 update private.push_deliveries set delivered_at=case when p_error is null then now() else null end,ticket_id=p_ticket,last_error=left(p_error,100),claimed_at=null,next_attempt_at=now()+interval '5 minutes'*attempts where notification_id=p_notification and device_id=p_device;
end $$;
revoke all on all tables in schema private from public,anon,authenticated;
revoke execute on function public.update_group(uuid,text,text),public.attach_receipt(uuid,text),public.group_report(uuid,date,date),public.claim_push_batch(),public.complete_push(uuid,uuid,text,text) from public,anon,authenticated;
grant execute on function public.update_group(uuid,text,text),public.attach_receipt(uuid,text),public.group_report(uuid,date,date) to authenticated;
grant execute on function public.claim_push_batch(),public.complete_push(uuid,uuid,text,text) to service_role;


-- 202610270005_recurring.sql
alter table public.recurring_expenses add column anchor_day int not null default 1 check(anchor_day between 1 and 31);
alter table public.recurring_expense_runs add column error_code text;
create function public.create_recurring(p_expense uuid,p_start date,p_end date,p_interval int,p_auto boolean) returns uuid language plpgsql security definer set search_path='' as $$
declare e public.expenses; template jsonb; r uuid; begin
 select * into e from public.expenses where id=p_expense and reversed_at is null; perform private.require_open(e.group_id);
 if not private.is_manager(e.group_id) or not public.has_group_feature(auth.uid(),e.group_id,'recurring') then raise exception 'Group Plus and manager required' using errcode='42501'; end if;
 if p_start<current_date or (p_end is not null and p_end<p_start) then raise exception 'Invalid recurrence dates'; end if;
 if e.split_method='itemized' then raise exception 'Itemized recurrence is not supported'; end if;
 select jsonb_build_object('group_id',e.group_id,'description',e.description,'amount_minor',e.amount_minor,'currency',e.currency,'category',e.category,'split_method',e.split_method,'notes',e.notes,
 'participants',(select jsonb_agg(jsonb_build_object('user_id',user_id,'value',input_value)) from public.expense_splits where expense_id=e.id),
 'payers',(select jsonb_agg(jsonb_build_object('user_id',user_id,'amount_minor',amount_minor)) from public.expense_payers where expense_id=e.id)) into template;
 insert into public.recurring_expenses(group_id,created_by,template,next_date,end_date,interval_months,auto_post,anchor_day) values(e.group_id,auth.uid(),template,p_start,p_end,p_interval,p_auto,extract(day from p_start)::int) returning id into r;
 perform private.audit(e.group_id,'recurring_created',r,jsonb_build_object('auto_post',p_auto)); return r;
end $$;
create function public.stop_recurring(p_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare g uuid; begin
 select group_id into g from public.recurring_expenses where id=p_id; perform private.require_open(g); if not private.is_manager(g) then raise exception 'Manager required'; end if;
 update public.recurring_expenses set active=false where id=p_id; perform private.audit(g,'recurring_stopped',p_id);
end $$;
create function public.approve_recurring_run(p_run uuid) returns uuid language plpgsql security definer set search_path='' as $$
declare run public.recurring_expense_runs; rule public.recurring_expenses; e uuid; begin
 select * into run from public.recurring_expense_runs where id=p_run for update; perform private.require_open(run.group_id);
 if not private.is_manager(run.group_id) or not public.has_group_feature(auth.uid(),run.group_id,'recurring') then raise exception 'Group Plus and manager required'; end if;
 if run.expense_id is not null then return run.expense_id; end if;
 if run.status<>'awaiting_approval' then raise exception 'Run is not awaiting approval'; end if;
 select * into rule from public.recurring_expenses where id=run.recurring_id;
 e:=public.create_expense(rule.template||jsonb_build_object('idempotency_key',run.id,'expense_date',run.scheduled_date));
 update public.recurring_expense_runs set expense_id=e,status='posted' where id=run.id; return e;
end $$;
create function public.run_recurring_batch() returns int language plpgsql security definer set search_path='' as $$
declare rule public.recurring_expenses; runid uuid; expense uuid; nextmonth date; lastday int; claimed int:=0; originalclaims text:=current_setting('request.jwt.claims',true); begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'Service role required'; end if;
 for rule in select * from public.recurring_expenses where active and next_date<=current_date and (end_date is null or next_date<=end_date) order by next_date limit 50 for update skip locked loop
  perform set_config('request.jwt.claims',jsonb_build_object('sub',rule.created_by,'role','authenticated')::text,true);
  if not public.has_group_feature(rule.created_by,rule.group_id,'recurring') or not private.is_manager(rule.group_id) or exists(select 1 from public.groups where id=rule.group_id and archived_at is not null) then
   perform set_config('request.jwt.claims',coalesce(originalclaims,'{}'),true); continue;
  end if;
  runid:=null;
  insert into public.recurring_expense_runs(group_id,recurring_id,scheduled_date) values(rule.group_id,rule.id,rule.next_date) on conflict do nothing returning id into runid;
  if runid is not null and rule.auto_post then
   begin
    expense:=public.create_expense(rule.template||jsonb_build_object('idempotency_key',runid,'expense_date',rule.next_date));
    update public.recurring_expense_runs set expense_id=expense,status='posted' where id=runid;
   exception when others then
    -- No partial financial writes survive the subtransaction. Manual review is required.
    update public.recurring_expense_runs set status='needs_review',error_code=sqlstate where id=runid;
   end;
  end if;
  nextmonth:=(date_trunc('month',rule.next_date)+make_interval(months=>rule.interval_months))::date;
  lastday:=extract(day from nextmonth+interval '1 month'-interval '1 day')::int;
  update public.recurring_expenses set next_date=nextmonth+least(rule.anchor_day,lastday)-1,active=(rule.end_date is null or nextmonth+least(rule.anchor_day,lastday)-1<=rule.end_date) where id=rule.id;
  claimed:=claimed+1; perform set_config('request.jwt.claims',coalesce(originalclaims,'{}'),true);
 end loop; return claimed;
end $$;
revoke execute on function public.create_recurring(uuid,date,date,int,boolean),public.stop_recurring(uuid),public.approve_recurring_run(uuid),public.run_recurring_batch() from public,anon,authenticated;
grant execute on function public.create_recurring(uuid,date,date,int,boolean),public.stop_recurring(uuid),public.approve_recurring_run(uuid) to authenticated;
grant execute on function public.run_recurring_batch() to service_role;


-- 202610270006_ledger_constraints.sql
-- Financial integrity also holds for accidental one-sided service-role writes.
alter table public.settlements add constraint settlements_id_group_unique unique(id,group_id);
alter table public.financial_ledger_entries add constraint ledger_expense_group foreign key(expense_id,group_id) references public.expenses(id,group_id);
alter table public.financial_ledger_entries add constraint ledger_settlement_group foreign key(settlement_id,group_id) references public.settlements(id,group_id);
alter table public.financial_ledger_entries add constraint ledger_member foreign key(group_id,user_id) references public.group_members(group_id,user_id);
alter table public.financial_ledger_entries add constraint ledger_event_source check((expense_id is not null and entry_type in ('expense','expense_reversal')) or (settlement_id is not null and entry_type in ('settlement','settlement_reversal')));
alter table public.expense_splits add constraint splits_member foreign key(group_id,user_id) references public.group_members(group_id,user_id);
alter table public.expense_payers add constraint payers_member foreign key(group_id,user_id) references public.group_members(group_id,user_id);
alter table public.expense_participants add constraint participants_member foreign key(group_id,user_id) references public.group_members(group_id,user_id);
create function private.validate_ledger_event() returns trigger language plpgsql security definer set search_path='' as $$
declare expected_currency text; begin
 if new.expense_id is not null then
  select currency into expected_currency from public.expenses where id=new.expense_id;
  if exists(select 1 from public.financial_ledger_entries where expense_id=new.expense_id and entry_type=new.entry_type group by currency having sum(delta_minor)<>0) then raise exception 'Expense ledger event must sum to zero'; end if;
 else
  select currency into expected_currency from public.settlements where id=new.settlement_id;
  if exists(select 1 from public.financial_ledger_entries where settlement_id=new.settlement_id and entry_type=new.entry_type group by currency having sum(delta_minor)<>0) then raise exception 'Settlement ledger event must sum to zero'; end if;
 end if;
 if new.currency<>expected_currency then raise exception 'Ledger currency must match source'; end if;
 return null;
end $$;
create constraint trigger ledger_zero_sum after insert on public.financial_ledger_entries deferrable initially deferred for each row execute function private.validate_ledger_event();
revoke execute on function private.validate_ledger_event() from public,anon,authenticated;
create index settlements_group_created on public.settlements(group_id,created_at desc,id);
create index invitations_group_created on public.group_invitations(group_id,created_at desc);
create index recurring_due on public.recurring_expenses(next_date) where active;
create index billing_group on public.billing_purchases(group_id);


-- 202610270007_rules.sql
alter table public.custom_split_rules add column currency text;
update public.custom_split_rules r set currency=g.currency from public.groups g where g.id=r.group_id;
alter table public.custom_split_rules alter column currency set not null;
alter table public.custom_split_rules add constraint rule_currency_supported check(currency in ('INR','USD','EUR','GBP','JPY','KWD'));
create or replace function public.save_split_rule(p_group uuid,p_name text,p_method text,p_participants jsonb) returns uuid language plpgsql security definer set search_path='' as $$ declare r uuid; curr text; begin
 perform private.require_open(p_group); if not private.is_manager(p_group) or not public.has_group_feature(auth.uid(),p_group,'custom_rules') then raise exception 'Group Plus and manager required'; end if;
 if jsonb_typeof(p_participants)<>'array' or jsonb_array_length(p_participants) not between 1 and 100 then raise exception 'Participants required'; end if;
 if (select count(distinct x->>'user_id') from jsonb_array_elements(p_participants) x)<>jsonb_array_length(p_participants) then raise exception 'Duplicate rule participants'; end if;
 if exists(select 1 from jsonb_array_elements(p_participants) x where x->>'value' is null or (x->>'value') !~ '^\d+$' or (x->>'value')::numeric>999999999999 or not exists(select 1 from public.group_members m where m.group_id=p_group and m.user_id=(x->>'user_id')::uuid and m.active)) then raise exception 'Invalid rule participant'; end if;
 if p_method='percentage' and (select sum((x->>'value')::numeric) from jsonb_array_elements(p_participants) x)<>10000 then raise exception 'Rule percentages must total 10000 basis points'; end if;
 select currency into curr from public.groups where id=p_group;
 insert into public.custom_split_rules(group_id,name,split_method,participants,created_by,currency) values(p_group,trim(p_name),p_method,p_participants,auth.uid(),curr) returning id into r; return r;
end $$;
create function public.rule_from_expense(p_expense uuid,p_name text) returns uuid language plpgsql security definer set search_path='' as $$ declare e public.expenses; participants jsonb; r uuid; begin
 select * into e from public.expenses where id=p_expense; perform private.require_open(e.group_id);
 if e.split_method='itemized' then raise exception 'Itemized rules are not supported'; end if;
 select jsonb_agg(jsonb_build_object('user_id',user_id,'value',input_value)) into participants from public.expense_splits where expense_id=e.id;
 r:=public.save_split_rule(e.group_id,p_name,e.split_method,participants); update public.custom_split_rules set currency=e.currency where id=r; return r;
end $$;
create function public.get_split_rule(p_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare rule public.custom_split_rules; begin
 select * into rule from public.custom_split_rules where id=p_id; perform private.require_open(rule.group_id);
 if not public.has_group_feature(auth.uid(),rule.group_id,'custom_rules') then raise exception 'Group Plus required' using errcode='42501'; end if;
 if exists(select 1 from jsonb_array_elements(rule.participants) p where not exists(select 1 from public.group_members where group_id=rule.group_id and user_id=(p->>'user_id')::uuid and active)) then raise exception 'Rule includes an inactive member; save a revised rule'; end if;
 return to_jsonb(rule);
end $$;
revoke execute on function public.rule_from_expense(uuid,text),public.get_split_rule(uuid) from public,anon,authenticated;
grant execute on function public.rule_from_expense(uuid,text),public.get_split_rule(uuid) to authenticated;


-- 202610270008_immutable_sources.sql
create function private.protect_expense_source() returns trigger language plpgsql set search_path='' as $$ begin
 if (to_jsonb(old)-array['reversed_at','version','updated_at'])<>(to_jsonb(new)-array['reversed_at','version','updated_at']) then raise exception 'Expense corrections must create a replacement record'; end if;
 return new;
end $$;
create trigger expense_source_immutable before update on public.expenses for each row execute function private.protect_expense_source();
create function private.protect_purchase_mapping() returns trigger language plpgsql set search_path='' as $$ begin
 if old.purchaser_id<>new.purchaser_id or old.group_id<>new.group_id or old.provider<>new.provider or old.original_transaction_id<>new.original_transaction_id then raise exception 'Purchase beneficiary mapping is immutable'; end if; return new;
end $$;
create trigger purchase_mapping_immutable before update on public.billing_purchases for each row execute function private.protect_purchase_mapping();
revoke execute on function private.protect_expense_source(),private.protect_purchase_mapping() from public,anon,authenticated;


-- 202610270009_settlement_plan.sql
create function public.settlement_plan(p_group uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare curr text; debtor record; creditor record; credits jsonb; needed bigint; available bigint; amount bigint; result jsonb:='[]'; begin
 perform private.require_member(p_group); if not public.has_group_feature(auth.uid(),p_group,'settlement_plan') then raise exception 'Group Plus required' using errcode='42501'; end if;
 if not exists(select 1 from public.groups where id=p_group and simplified_settlements) then raise exception 'Simplified settlement suggestions are disabled'; end if;
 for curr in select distinct currency from public.financial_ledger_entries where group_id=p_group order by currency loop
  credits:='{}';
  for creditor in select user_id,sum(delta_minor)::bigint amount from public.financial_ledger_entries where group_id=p_group and currency=curr group by user_id having sum(delta_minor)>0 loop
   credits:=jsonb_set(credits,array[creditor.user_id::text],to_jsonb(creditor.amount));
  end loop;
  for debtor in select user_id,-sum(delta_minor)::bigint amount from public.financial_ledger_entries where group_id=p_group and currency=curr group by user_id having sum(delta_minor)<0 order by sum(delta_minor),user_id loop
   needed:=debtor.amount;
   for creditor in select key::uuid uid,value::bigint amount from jsonb_each_text(credits) order by value::bigint desc,key loop
    available:=(credits->>creditor.uid::text)::bigint; amount:=least(needed,available);
    if amount>0 then result:=result||jsonb_build_array(jsonb_build_object('currency',curr,'from_user',debtor.user_id,'to_user',creditor.uid,'amount_minor',amount)); credits:=jsonb_set(credits,array[creditor.uid::text],to_jsonb(available-amount)); needed:=needed-amount; end if;
    exit when needed=0;
   end loop;
  end loop;
 end loop;
 return result;
end $$;
create function public.set_settlement_simplification(p_group uuid,p_enabled boolean) returns void language plpgsql security definer set search_path='' as $$ begin
 perform private.require_open(p_group); if not private.is_manager(p_group) then raise exception 'Manager required'; end if;
 update public.groups set simplified_settlements=p_enabled,updated_at=now() where id=p_group; perform private.audit(p_group,'settlement_suggestions_changed',p_group,jsonb_build_object('enabled',p_enabled));
end $$;
revoke execute on function public.settlement_plan(uuid),public.set_settlement_simplification(uuid,boolean) from public,anon,authenticated;
grant execute on function public.settlement_plan(uuid),public.set_settlement_simplification(uuid,boolean) to authenticated;


-- 202610290000_complimentary_access.sql
-- Operator-issued access is separate from a store purchase. Existing RLS and
-- table grants allow only trusted backend/operators to issue entitlements.
alter table public.group_subscription_entitlements
  alter column purchase_id drop not null,
  add column complimentary_reason text,
  add constraint entitlement_source_required check (
    (purchase_id is not null and complimentary_reason is null)
    or (purchase_id is null and length(trim(complimentary_reason)) between 10 and 500
        and complimentary_reason is not null and not renews)
  );

-- A later verified store purchase replaces complimentary access normally.
create function private.normalize_entitlement_source() returns trigger
language plpgsql set search_path='' as $$
begin
  if new.purchase_id is not null then new.complimentary_reason := null; end if;
  return new;
end $$;
revoke all on function private.normalize_entitlement_source() from public;
create trigger entitlement_source before insert or update
on public.group_subscription_entitlements for each row
execute function private.normalize_entitlement_source();


-- 202610300000_member_experience.sql
-- Use the supplied name for email accounts and Google profile metadata for OAuth.
create or replace function private.on_user() returns trigger language plpgsql security definer set search_path='' as $$ begin
 insert into public.profiles(id,display_name) values(new.id,coalesce(nullif(left(trim(new.raw_user_meta_data->>'display_name'),80),''),nullif(left(trim(new.raw_user_meta_data->>'full_name'),80),''),nullif(left(trim(new.raw_user_meta_data->>'name'),80),''),'Tracksy member'));
 insert into public.user_preferences(user_id) values(new.id); insert into public.notification_preferences(user_id) values(new.id); return new;
end $$;
update public.profiles p set display_name=left(coalesce(nullif(trim(u.raw_user_meta_data->>'display_name'),''),nullif(trim(u.raw_user_meta_data->>'full_name'),''),nullif(trim(u.raw_user_meta_data->>'name'),'')),80),updated_at=now()
from auth.users u where p.id=u.id and p.display_name='Tracksy member' and coalesce(nullif(trim(u.raw_user_meta_data->>'display_name'),''),nullif(trim(u.raw_user_meta_data->>'full_name'),''),nullif(trim(u.raw_user_meta_data->>'name'),'')) is not null;

-- Membership has no expense-allocation side effect. Existing immutable splits and
-- ledger entries are deliberately untouched by invitations, joins and this migration.

create or replace function private.reverse_expense(p_expense uuid,p_version int) returns uuid language plpgsql security definer set search_path='' as $$
declare e public.expenses; begin
 select * into e from public.expenses where id=p_expense for update; perform private.require_open(e.group_id);
 -- Every active member may edit or reverse an expense; access is checked above.
 if e.version<>p_version or e.reversed_at is not null then raise exception 'Expense changed. Refresh before trying again' using errcode='40001'; end if;
 insert into public.financial_ledger_entries(group_id,user_id,currency,delta_minor,expense_id,entry_type) select group_id,user_id,currency,-delta_minor,expense_id,'expense_reversal' from public.financial_ledger_entries where expense_id=p_expense and entry_type='expense';
 update public.expenses set reversed_at=now(),version=version+1,updated_at=now() where id=p_expense; perform private.audit(e.group_id,'expense_reversed',p_expense,jsonb_build_object('description',e.description,'currency',e.currency,'amount_minor',e.amount_minor,'previous_version',e.version)); return p_expense;
end $$;

create or replace function public.create_expense(p jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid:=private.require_user(); g uuid:=(p->>'group_id')::uuid; total bigint:=(p->>'amount_minor')::bigint;
 curr text:=p->>'currency'; method text:=p->>'split_method'; participants jsonb:=p->'participants'; n int; denom numeric; funded numeric; e uuid; prior uuid; before_record jsonb; row record; key uuid:=(p->>'idempotency_key')::uuid;
begin
 perform private.require_open(g); if key is null then raise exception 'Idempotency key required'; end if;
 prior:=private.replay(key,'expense',p); if prior is not null then return prior; end if;
 perform 1 from public.groups where id=g for update;
 perform private.require_open(g);
 if total is null or total<1 or total>999999999999 then raise exception 'Invalid total'; end if;
 if curr is null or curr not in ('INR','USD','EUR','GBP','JPY','KWD') then raise exception 'Unsupported currency'; end if;
 if jsonb_typeof(participants)<>'array' or jsonb_typeof(p->'payers')<>'array' then raise exception 'Participants and payers required'; end if;
 if method='itemized' then participants:=private.itemized_shares(total,p->'items'); end if;
 n:=jsonb_array_length(participants);
 if n<1 or n>100 or jsonb_array_length(p->'payers') not between 1 and 100 then raise exception 'Invalid participant count'; end if;
 if (select count(distinct x->>'user_id') from jsonb_array_elements(participants) x)<>n then raise exception 'Duplicate participants'; end if;
 if (select count(distinct x->>'user_id') from jsonb_array_elements(p->'payers') x)<>jsonb_array_length(p->'payers') then raise exception 'Duplicate payers'; end if;
 for row in select x->>'user_id' uid,x->>'value' val from jsonb_array_elements(participants) x loop
  if not exists(select 1 from public.group_members where group_id=g and user_id=row.uid::uuid and active) then raise exception 'Participant is not an active member'; end if;
  if method<>'equal' and (row.val is null or row.val !~ '^\d+$' or row.val::numeric>999999999999) then raise exception 'Invalid split value'; end if;
 end loop;
 for row in select x->>'user_id' uid,x->>'amount_minor' val from jsonb_array_elements(p->'payers') x loop
  if not exists(select 1 from public.group_members where group_id=g and user_id=row.uid::uuid and active) then raise exception 'Payer is not an active member'; end if;
  if row.val is null or row.val !~ '^\d+$' or row.val::numeric>999999999999 then raise exception 'Invalid payer amount'; end if;
 end loop;
 select sum((x->>'amount_minor')::numeric) into funded from jsonb_array_elements(p->'payers') x;
 if funded<>total then raise exception 'Payers must fund the total'; end if;
 select sum(case when method='equal' then 1 else (x->>'value')::numeric end) into denom from jsonb_array_elements(participants) x;
 if method in ('exact','custom','itemized') and denom<>total then raise exception 'Shares must equal total'; end if;
 if method='percentage' and denom<>10000 then raise exception 'Percentages must total 10000 basis points'; end if;
 if denom<=0 then raise exception 'Positive weights required'; end if;
 if method='itemized' and not public.has_group_feature(u,g,'itemized') then raise exception 'Group Plus required' using errcode='42501'; end if;
 if p->>'replaces_id' is not null then
  if not exists(select 1 from public.expenses where id=(p->>'replaces_id')::uuid and group_id=g) then raise exception 'Correction group mismatch'; end if;
  if p->>'expected_version' is null then raise exception 'Expected version required'; end if;
  select to_jsonb(old_expense)||jsonb_build_object('participants',(select jsonb_agg(to_jsonb(s)) from public.expense_splits s where s.expense_id=old_expense.id),'payers',(select jsonb_agg(to_jsonb(f)) from public.expense_payers f where f.expense_id=old_expense.id)) into before_record from public.expenses old_expense where old_expense.id=(p->>'replaces_id')::uuid;
  perform private.reverse_expense((p->>'replaces_id')::uuid,(p->>'expected_version')::int);
 end if;
 if (select count(*) from public.expenses where created_by=u and created_at>now()-interval '1 hour')>=300 then raise exception 'Expense rate limit'; end if;
 insert into public.expenses(group_id,created_by,description,amount_minor,currency,category,split_method,expense_date,notes,replaces_id)
 values(g,u,trim(p->>'description'),total,curr,p->>'category',method,(p->>'expense_date')::date,coalesce(p->>'notes',''),(p->>'replaces_id')::uuid) returning id into e;
 insert into public.expense_payers select e,g,(x->>'user_id')::uuid,(x->>'amount_minor')::bigint from jsonb_array_elements(p->'payers') x;
 if method='itemized' then insert into public.expense_items(expense_id,group_id,description,amount_minor,allocations) select e,g,x->>'description',(x->>'amount_minor')::bigint,x->'allocations' from jsonb_array_elements(p->'items') x; end if;
 insert into public.expense_participants select e,g,(x->>'user_id')::uuid from jsonb_array_elements(participants) x;
 if method in ('exact','custom','itemized') then
  insert into public.expense_splits select e,g,(x->>'user_id')::uuid,(x->>'value')::bigint,(x->>'value')::bigint from jsonb_array_elements(participants) x;
 else
  -- NUMERIC multiplication avoids bigint overflow. No floating point is involved.
  insert into public.expense_splits(expense_id,group_id,user_id,amount_minor,input_value)
  with inputs as (select (x->>'user_id')::uuid uid,case when method='equal' then 1 else (x->>'value')::numeric end weight from jsonb_array_elements(participants) x),
  base as (select uid,weight,floor(total::numeric*weight/denom) amount,mod(total::numeric*weight,denom) rem from inputs),
  ranked as (select *,row_number() over(order by rem desc,uid) rank,total-sum(amount) over() leftover from base)
  select e,g,uid,(amount+case when rank<=leftover then 1 else 0 end)::bigint,weight::bigint from ranked;
 end if;
 insert into public.financial_ledger_entries(group_id,user_id,currency,delta_minor,expense_id,entry_type)
 select g,uid,curr,sum(delta)::bigint,e,'expense' from (select user_id uid,amount_minor delta from public.expense_payers where expense_id=e union all select user_id,-amount_minor from public.expense_splits where expense_id=e) x group by uid;
 if (select sum(delta_minor) from public.financial_ledger_entries where expense_id=e)<>0 then raise exception 'Ledger must balance'; end if;
 perform private.audit(g,case when p->>'replaces_id' is null then 'expense_added' else 'expense_corrected' end,e,jsonb_build_object('description',p->>'description','currency',curr,'amount_minor',total,'previous_expense_id',p->>'replaces_id','before',before_record,'after',p-'idempotency_key'));
 insert into public.notifications(user_id,group_id,kind) select user_id,g,'expense_added' from public.group_members where group_id=g and active and user_id<>u;
 perform private.remember(key,'expense',p,e); return e;
end $$;



-- 202610300001_group_email.sql
-- Invitations and reminders are user-initiated, rate-limited and delivered only
-- by a server function. Tokens and recipient addresses stay in a private outbox.
create table private.group_mail (
 id uuid primary key default gen_random_uuid(),created_by uuid not null references public.profiles,
 group_id uuid not null references public.groups,kind text not null check(kind in('invite','reminder')),
 recipient text not null,recipient_id uuid references public.profiles,currency text,
 invitation_id uuid references public.group_invitations,invite_token text,request_key uuid not null,
 payload_hash text not null,status text not null default 'pending' check(status in('pending','sending','sent','failed')),
 attempts int not null default 0,claimed_at timestamptz,sent_at timestamptz,created_at timestamptz not null default now(),
 unique(created_by,request_key)
);
create index group_mail_cooldown on private.group_mail(group_id,recipient_id,currency,created_at desc);
alter table private.group_mail enable row level security;

-- Any active member can invite a friend. A link remains a single-use, expiring
-- invitation; joining never recalculates earlier expense allocations.
create or replace function public.invite_member(p_group uuid,p_email text default null) returns text language plpgsql security definer set search_path='' as $$
declare token text:=replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-','');mail text:=nullif(lower(trim(p_email)),''); begin
 perform private.require_open(p_group);
 if mail is not null and (length(mail)>254 or mail !~ '^[A-Za-z0-9.!#$%&*+/=?^_`{|}~-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$') then raise exception 'Enter a valid email address'; end if;
 if (select count(*) from public.group_invitations where invited_by=auth.uid() and created_at>now()-interval '1 hour')>=30 then raise exception 'Invitation limit reached. Try again later'; end if;
 insert into public.group_invitations(group_id,token_hash,email,invited_by) values(p_group,encode(sha256(convert_to(token,'UTF8')),'hex'),mail,auth.uid());
 perform private.audit(p_group,'invitation_created',null); return token;
end $$;

create function public.invitation_preview(p_token text) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare inv public.group_invitations;result jsonb;begin
 if p_token !~ '^[a-f0-9]{64}$' then raise exception 'This invitation link is not valid'; end if;
 select * into inv from public.group_invitations where token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex');
 if inv.id is null or inv.expires_at<=now() or inv.accepted_by is not null then raise exception 'This invitation has expired or has already been used'; end if;
 select jsonb_build_object('group_name',g.name,'inviter',p.display_name,'expires_at',inv.expires_at,'email_bound',inv.email is not null) into result from public.groups g join public.profiles p on p.id=inv.invited_by where g.id=inv.group_id and g.archived_at is null;
 if result is null then raise exception 'This group is no longer available'; end if;return result;
end $$;

create function public.reminder_targets(p_group uuid) returns table(user_id uuid,display_name text,currency text,balance_minor bigint,can_remind boolean,last_sent_at timestamptz) language plpgsql stable security definer set search_path='' as $$
begin perform private.require_member(p_group);return query
 with balances as(select l.user_id,l.currency,sum(l.delta_minor)::bigint balance from public.financial_ledger_entries l where l.group_id=p_group group by l.user_id,l.currency)
 select b.user_id,p.display_name,b.currency,b.balance,
 b.user_id<>auth.uid() and b.balance<0 and coalesce(n.reminders,true) and exists(select 1 from balances mine where mine.user_id=auth.uid() and mine.currency=b.currency and mine.balance>0)
 and not exists(select 1 from private.group_mail mail where mail.group_id=p_group and mail.recipient_id=b.user_id and mail.currency=b.currency and mail.kind='reminder' and mail.status in('sent','sending','pending') and mail.created_at>now()-interval '24 hours'),
 (select max(mail.sent_at) from private.group_mail mail where mail.group_id=p_group and mail.recipient_id=b.user_id and mail.currency=b.currency and mail.kind='reminder')
 from balances b join public.profiles p on p.id=b.user_id join public.group_members m on m.group_id=p_group and m.user_id=b.user_id and m.active left join public.notification_preferences n on n.user_id=b.user_id;
end $$;

create function public.prepare_group_mail(p_group uuid,p_kind text,p_key uuid,p_email text default null,p_recipient uuid default null,p_currency text default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=private.require_user();job private.group_mail;mail text;token text;invite uuid;hash text;eligible boolean;begin
 perform private.require_open(p_group);
 if p_key is null or p_kind not in('invite','reminder') then raise exception 'Invalid email request'; end if;
 hash:=encode(sha256(convert_to(jsonb_build_object('group',p_group,'kind',p_kind,'email',lower(trim(p_email)),'recipient',p_recipient,'currency',p_currency)::text,'UTF8')),'hex');
 perform pg_advisory_xact_lock(hashtextextended('group-mail:'||u::text,0));
 select * into job from private.group_mail where created_by=u and request_key=p_key for update;
 if job.id is not null then
  if job.payload_hash<>hash then raise exception 'Request key was already used for different email details'; end if;
  return jsonb_build_object('id',job.id,'status',job.status,'link',case when job.kind='invite' and job.invite_token is not null then 'https://tracksy-support.coralprawn64.chatgpt.site/join/?token='||job.invite_token else null end);
 end if;
 if (select count(*) from private.group_mail where created_by=u and created_at>now()-interval '1 hour')>=30 then raise exception 'Email limit reached. Try again later'; end if;
 if p_kind='invite' then
  mail:=lower(trim(p_email));if mail is null or mail='' then raise exception 'Enter an email address'; end if;
  if exists(select 1 from auth.users a join public.group_members m on m.user_id=a.id where m.group_id=p_group and m.active and lower(a.email)=mail) then raise exception 'This person is already in the group'; end if;
  if exists(select 1 from private.group_mail old where old.created_by=u and old.group_id=p_group and old.recipient=mail and old.kind='invite' and old.created_at>now()-interval '5 minutes' and old.status in('pending','sending','sent')) then raise exception 'An invitation was sent recently. Please wait before sending again'; end if;
  token:=public.invite_member(p_group,mail);
  select id into invite from public.group_invitations where token_hash=encode(sha256(convert_to(token,'UTF8')),'hex');
 else
  -- Serialize reminders across all senders to the same member/currency.
  perform pg_advisory_xact_lock(hashtextextended(p_group::text||coalesce(p_recipient::text,'')||coalesce(p_currency,''),0));
  select t.can_remind into eligible from public.reminder_targets(p_group) t where t.user_id=p_recipient and t.currency=p_currency;
  if not coalesce(eligible,false) then raise exception 'A reminder is not available for this balance. It may be settled, disabled or recently reminded'; end if;
  select lower(email) into mail from auth.users where id=p_recipient and email_confirmed_at is not null;
  if mail is null then raise exception 'This member needs a verified email before receiving reminders'; end if;
 end if;
 insert into private.group_mail(created_by,group_id,kind,recipient,recipient_id,currency,invitation_id,invite_token,request_key,payload_hash)
 values(u,p_group,p_kind,mail,p_recipient,p_currency,invite,token,p_key,hash) returning * into job;
 return jsonb_build_object('id',job.id,'status',job.status,'link',case when token is not null then 'https://tracksy-support.coralprawn64.chatgpt.site/join/?token='||token else null end);
end $$;

create function public.claim_group_mail(p_id uuid,p_user uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare job private.group_mail;begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'Service role required' using errcode='42501';end if;
 select * into job from private.group_mail where id=p_id and created_by=p_user for update;
 if job.id is null then raise exception 'Email request not found';end if;
 if job.status='sent' then return jsonb_build_object('status','sent');end if;
 if job.status='sending' and job.claimed_at>now()-interval '2 minutes' then raise exception 'This email is already being sent';end if;
 if job.attempts>=3 or job.created_at<now()-interval '1 day' then raise exception 'Email retries exhausted. Create a new invitation';end if;
 if job.kind='invite' and not exists(select 1 from public.group_invitations i where i.id=job.invitation_id and i.expires_at>now() and i.accepted_at is null) then raise exception 'Invitation expired or already used';end if;
 if job.kind='reminder' and (not exists(select 1 from public.group_members m where m.group_id=job.group_id and m.user_id=job.created_by and m.active) or not exists(select 1 from public.notification_preferences n where n.user_id=job.recipient_id and n.reminders)) then raise exception 'Reminder permission changed';end if;
 update private.group_mail set status='sending',attempts=attempts+1,claimed_at=now() where id=p_id;
 return(select jsonb_build_object('status','sending','recipient',job.recipient,'group_name',g.name,'sender_name',p.display_name,'kind',job.kind,'link',case when job.kind='invite' then 'https://tracksy-support.coralprawn64.chatgpt.site/join/?token='||job.invite_token else 'https://tracksy-support.coralprawn64.chatgpt.site/open/' end) from public.groups g join public.profiles p on p.id=job.created_by where g.id=job.group_id and g.archived_at is null);
end $$;

create function public.complete_group_mail(p_id uuid,p_user uuid,p_success boolean) returns void language plpgsql security definer set search_path='' as $$
declare job private.group_mail;begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'Service role required' using errcode='42501';end if;
 select * into job from private.group_mail where id=p_id and created_by=p_user for update;
 if job.id is null or job.status<>'sending' then return;end if;
 update private.group_mail set status=case when p_success then 'sent' else 'failed' end,sent_at=case when p_success then now() else null end,claimed_at=null where id=p_id;
 if p_success then insert into public.expense_audit_events(group_id,actor_id,event_type,entity_id,detail) values(job.group_id,p_user,case when job.kind='invite' then 'invitation_emailed' else 'reminder_emailed' end,job.recipient_id,jsonb_build_object('recipient_id',job.recipient_id));end if;
end $$;

revoke all on private.group_mail from public,anon,authenticated;
revoke execute on function public.invitation_preview(text),public.reminder_targets(uuid),public.prepare_group_mail(uuid,text,uuid,text,uuid,text),public.claim_group_mail(uuid,uuid),public.complete_group_mail(uuid,uuid,boolean) from public,anon,authenticated;
grant execute on function public.invitation_preview(text) to anon,authenticated;
grant execute on function public.reminder_targets(uuid),public.prepare_group_mail(uuid,text,uuid,text,uuid,text) to authenticated;
grant execute on function public.claim_group_mail(uuid,uuid),public.complete_group_mail(uuid,uuid,boolean) to service_role;
-- Realtime uses the recipient RLS policy, never a broad notifications read grant.
alter publication supabase_realtime add table public.notifications;


-- 202610300002_expense_history.sql
create or replace function public.create_expense(p jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid:=private.require_user(); g uuid:=(p->>'group_id')::uuid; total bigint:=(p->>'amount_minor')::bigint;
 curr text:=p->>'currency'; method text:=p->>'split_method'; participants jsonb:=p->'participants'; n int; denom numeric; funded numeric; e uuid; prior uuid; before_record jsonb; row record; key uuid:=(p->>'idempotency_key')::uuid;
begin
 perform private.require_open(g); if key is null then raise exception 'Idempotency key required'; end if;
 prior:=private.replay(key,'expense',p); if prior is not null then return prior; end if;
 perform 1 from public.groups where id=g for update;
 perform private.require_open(g);
 if total is null or total<1 or total>999999999999 then raise exception 'Invalid total'; end if;
 if curr is null or curr not in ('INR','USD','EUR','GBP','JPY','KWD') then raise exception 'Unsupported currency'; end if;
 if jsonb_typeof(participants)<>'array' or jsonb_typeof(p->'payers')<>'array' then raise exception 'Participants and payers required'; end if;
 if method='itemized' then participants:=private.itemized_shares(total,p->'items'); end if;
 n:=jsonb_array_length(participants);
 if n<1 or n>100 or jsonb_array_length(p->'payers') not between 1 and 100 then raise exception 'Invalid participant count'; end if;
 if (select count(distinct x->>'user_id') from jsonb_array_elements(participants) x)<>n then raise exception 'Duplicate participants'; end if;
 if (select count(distinct x->>'user_id') from jsonb_array_elements(p->'payers') x)<>jsonb_array_length(p->'payers') then raise exception 'Duplicate payers'; end if;
 for row in select x->>'user_id' uid,x->>'value' val from jsonb_array_elements(participants) x loop
  if not exists(select 1 from public.group_members where group_id=g and user_id=row.uid::uuid and (active or (p->>'replaces_id' is not null and exists(select 1 from public.expense_splits old where old.expense_id=(p->>'replaces_id')::uuid and old.group_id=g and old.user_id=row.uid::uuid)))) then raise exception 'Participant is not an active member'; end if;
  if method<>'equal' and (row.val is null or row.val !~ '^\d+$' or row.val::numeric>999999999999) then raise exception 'Invalid split value'; end if;
 end loop;
 for row in select x->>'user_id' uid,x->>'amount_minor' val from jsonb_array_elements(p->'payers') x loop
  if not exists(select 1 from public.group_members where group_id=g and user_id=row.uid::uuid and (active or (p->>'replaces_id' is not null and exists(select 1 from public.expense_payers old where old.expense_id=(p->>'replaces_id')::uuid and old.group_id=g and old.user_id=row.uid::uuid)))) then raise exception 'Payer is not an active member'; end if;
  if row.val is null or row.val !~ '^\d+$' or row.val::numeric>999999999999 then raise exception 'Invalid payer amount'; end if;
 end loop;
 select sum((x->>'amount_minor')::numeric) into funded from jsonb_array_elements(p->'payers') x;
 if funded<>total then raise exception 'Payers must fund the total'; end if;
 select sum(case when method='equal' then 1 else (x->>'value')::numeric end) into denom from jsonb_array_elements(participants) x;
 if method in ('exact','custom','itemized') and denom<>total then raise exception 'Shares must equal total'; end if;
 if method='percentage' and denom<>10000 then raise exception 'Percentages must total 10000 basis points'; end if;
 if denom<=0 then raise exception 'Positive weights required'; end if;
 if method='itemized' and not public.has_group_feature(u,g,'itemized') then raise exception 'Group Plus required' using errcode='42501'; end if;
 if p->>'replaces_id' is not null then
  if not exists(select 1 from public.expenses where id=(p->>'replaces_id')::uuid and group_id=g) then raise exception 'Correction group mismatch'; end if;
  if p->>'expected_version' is null then raise exception 'Expected version required'; end if;
  select to_jsonb(old_expense)||jsonb_build_object('participants',(select jsonb_agg(to_jsonb(s)) from public.expense_splits s where s.expense_id=old_expense.id),'payers',(select jsonb_agg(to_jsonb(f)) from public.expense_payers f where f.expense_id=old_expense.id)) into before_record from public.expenses old_expense where old_expense.id=(p->>'replaces_id')::uuid;
  perform private.reverse_expense((p->>'replaces_id')::uuid,(p->>'expected_version')::int);
 end if;
 if (select count(*) from public.expenses where created_by=u and created_at>now()-interval '1 hour')>=300 then raise exception 'Expense rate limit'; end if;
 insert into public.expenses(group_id,created_by,description,amount_minor,currency,category,split_method,expense_date,notes,replaces_id)
 values(g,u,trim(p->>'description'),total,curr,p->>'category',method,(p->>'expense_date')::date,coalesce(p->>'notes',''),(p->>'replaces_id')::uuid) returning id into e;
 insert into public.expense_payers select e,g,(x->>'user_id')::uuid,(x->>'amount_minor')::bigint from jsonb_array_elements(p->'payers') x;
 if method='itemized' then insert into public.expense_items(expense_id,group_id,description,amount_minor,allocations) select e,g,x->>'description',(x->>'amount_minor')::bigint,x->'allocations' from jsonb_array_elements(p->'items') x; end if;
 insert into public.expense_participants select e,g,(x->>'user_id')::uuid from jsonb_array_elements(participants) x;
 if method in ('exact','custom','itemized') then
  insert into public.expense_splits select e,g,(x->>'user_id')::uuid,(x->>'value')::bigint,(x->>'value')::bigint from jsonb_array_elements(participants) x;
 else
  -- NUMERIC multiplication avoids bigint overflow. No floating point is involved.
  insert into public.expense_splits(expense_id,group_id,user_id,amount_minor,input_value)
  with inputs as (select (x->>'user_id')::uuid uid,case when method='equal' then 1 else (x->>'value')::numeric end weight from jsonb_array_elements(participants) x),
  base as (select uid,weight,floor(total::numeric*weight/denom) amount,mod(total::numeric*weight,denom) rem from inputs),
  ranked as (select *,row_number() over(order by rem desc,uid) rank,total-sum(amount) over() leftover from base)
  select e,g,uid,(amount+case when rank<=leftover then 1 else 0 end)::bigint,weight::bigint from ranked;
 end if;
 insert into public.financial_ledger_entries(group_id,user_id,currency,delta_minor,expense_id,entry_type)
 select g,uid,curr,sum(delta)::bigint,e,'expense' from (select user_id uid,amount_minor delta from public.expense_payers where expense_id=e union all select user_id,-amount_minor from public.expense_splits where expense_id=e) x group by uid;
 if (select sum(delta_minor) from public.financial_ledger_entries where expense_id=e)<>0 then raise exception 'Ledger must balance'; end if;
 perform private.audit(g,case when p->>'replaces_id' is null then 'expense_added' else 'expense_corrected' end,e,jsonb_build_object('description',p->>'description','currency',curr,'amount_minor',total,'previous_expense_id',p->>'replaces_id','before',before_record,'after',p-'idempotency_key'));
 insert into public.notifications(user_id,group_id,kind) select user_id,g,'expense_added' from public.group_members where group_id=g and active and user_id<>u;
 perform private.remember(key,'expense',p,e); return e;
end $$;



create index expenses_previous_version on public.expenses(replaces_id) where replaces_id is not null;
create function public.expense_versions(p_expense uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare g uuid;result jsonb;begin
 select group_id into g from public.expenses where id=p_expense;perform private.require_member(g);
 with recursive ancestors as(
  select e.id,e.replaces_id,0 depth from public.expenses e where e.id=p_expense
  union all select e.id,e.replaces_id,a.depth+1 from public.expenses e join ancestors a on e.id=a.replaces_id where e.group_id=g and a.depth<100
 ),root as(select id from ancestors order by depth desc limit 1),versions as(
  select e.*,0 depth from public.expenses e join root r on e.id=r.id
  union all select e.*,v.depth+1 from public.expenses e join versions v on e.replaces_id=v.id where e.group_id=g and v.depth<100
 )select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'description',v.description,'amount_minor',v.amount_minor,'currency',v.currency,'category',v.category,'expense_date',v.expense_date,'editor',p.display_name,'actor_id',v.created_by,'created_at',v.created_at,'reversed_at',v.reversed_at,'previous_id',v.replaces_id,'participants',(select coalesce(jsonb_agg(jsonb_build_object('user_id',s.user_id,'name',person.display_name,'amount_minor',s.amount_minor)),'[]') from public.expense_splits s join public.profiles person on person.id=s.user_id where s.expense_id=v.id)) order by v.depth desc),'[]') into result from versions v join public.profiles p on p.id=v.created_by;
 return result;
end $$;
revoke execute on function public.expense_versions(uuid) from public,anon;
grant execute on function public.expense_versions(uuid) to authenticated;


-- 202610300003_invitation_usability.sql
create or replace function public.accept_invitation(p_token text) returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid:=private.require_user(); inv public.group_invitations; verified boolean; mail text; begin
 select email_confirmed_at is not null, lower(email) into verified,mail from auth.users where id=u;
 if not coalesce(verified,false) then raise exception 'Verify your email before joining'; end if;
 select * into inv from public.group_invitations where token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex') for update;
 if inv.accepted_by=u and exists(select 1 from public.group_members m where m.group_id=inv.group_id and m.user_id=u and m.active) then return inv.group_id;end if;
 if inv.id is null or inv.expires_at<=now() or inv.accepted_by is not null then raise exception 'Invalid, expired, or used invitation'; end if;
 if inv.email is not null and inv.email<>mail then raise exception 'Invitation belongs to another email' using errcode='42501'; end if;
 perform 1 from public.groups where id=inv.group_id and archived_at is null for update;
 if not found then raise exception 'Group is archived'; end if;
 if (select count(*) from public.group_members where group_id=inv.group_id and active)>=100 then raise exception 'Group member limit reached'; end if;
 if exists(select 1 from public.group_members where group_id=inv.group_id and user_id=u and active) then return inv.group_id;end if;
 insert into public.group_members(group_id,user_id) values(inv.group_id,u) on conflict(group_id,user_id) do update set active=true,role='member',billing_manager=false,left_at=null;
 update public.group_invitations set accepted_by=u,accepted_at=now() where id=inv.id; perform private.audit(inv.group_id,'member_joined',u); return inv.group_id;
end $$;


create or replace function public.invitation_preview(p_token text) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare inv public.group_invitations;result jsonb;existing boolean;begin
 if p_token !~ '^[a-f0-9]{64}$' then raise exception 'This invitation link is not valid'; end if;
 select * into inv from public.group_invitations where token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex');
 existing:=inv.id is not null and exists(select 1 from public.group_members m where m.group_id=inv.group_id and m.user_id=auth.uid() and m.active);
 if inv.id is null or ((inv.expires_at<=now() or inv.accepted_by is not null) and not(existing and (inv.accepted_by is null or inv.accepted_by=auth.uid()))) then raise exception 'This invitation has expired or has already been used'; end if;
 select jsonb_build_object('group_name',g.name,'inviter',p.display_name,'expires_at',inv.expires_at,'email_bound',inv.email is not null,'already_member',existing) into result from public.groups g join public.profiles p on p.id=inv.invited_by where g.id=inv.group_id and g.archived_at is null;
 if result is null then raise exception 'This group is no longer available'; end if;return result;
end $$;


-- 202611040000_group_lifecycle.sql
-- Groups are removed from member access without destroying the append-only
-- financial ledger. Only an owner can delete a fully settled group.
alter table public.groups add column deleted_at timestamptz;

create or replace function public.is_group_member(p_group uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.group_members m join public.groups g on g.id=m.group_id
 where m.group_id=p_group and m.user_id=auth.uid() and m.active and g.deleted_at is null)
$$;

-- Serialize lifecycle changes with writes. A transaction that has checked an
-- open group holds its shared row lock until its mutation commits.
create or replace function private.require_open(p_group uuid) returns void
language plpgsql volatile security definer set search_path='' as $$
declare archived timestamptz; removed timestamptz; begin
 perform private.require_member(p_group);
 select archived_at,deleted_at into archived,removed from public.groups where id=p_group for share;
 if not found or removed is not null then raise exception 'Group is no longer available'; end if;
 if archived is not null then raise exception 'Group is archived'; end if;
end $$;

create function public.restore_group(p_group uuid) returns void
language plpgsql security definer set search_path='' as $$
declare g public.groups; begin
 perform private.require_member(p_group);
 select * into g from public.groups where id=p_group for update;
 if g.owner_id<>auth.uid() then raise exception 'Owner required' using errcode='42501'; end if;
 if g.deleted_at is not null then raise exception 'Deleted groups cannot be restored'; end if;
 if g.archived_at is null then return; end if;
 update public.groups set archived_at=null,updated_at=now() where id=p_group;
 perform private.audit(p_group,'group_restored',p_group);
end $$;

create function public.delete_group(p_group uuid) returns void
language plpgsql security definer set search_path='' as $$
declare g public.groups; begin
 perform private.require_member(p_group);
 select * into g from public.groups where id=p_group for update;
 if g.owner_id<>auth.uid() then raise exception 'Owner required' using errcode='42501'; end if;
 if exists(select 1 from public.financial_ledger_entries where group_id=p_group group by user_id,currency having sum(delta_minor)<>0) then
  raise exception 'Settle every member''s outstanding balances in each currency before deleting this group'; end if;
 if exists(select 1 from public.settlements where group_id=p_group and status in('pending','disputed')) then
  raise exception 'Resolve pending or disputed payments before deleting this group'; end if;
 if exists(select 1 from public.billing_purchases where group_id=p_group and renews and status in('active','grace') and current_period_end>now()) then
  raise exception 'Cancel the group''s renewing store subscription before deleting this group'; end if;
 perform private.audit(p_group,'group_deleted',p_group,jsonb_build_object('name',g.name,'records_retained',true));
 update public.recurring_expenses set active=false where group_id=p_group and active;
 update public.group_invitations set expires_at=least(expires_at,now()) where group_id=p_group;
 update private.group_mail set status='failed',invite_token=null where group_id=p_group and status in('pending','sending');
 update public.groups set deleted_at=now(),archived_at=coalesce(archived_at,now()),updated_at=now() where id=p_group;
end $$;

revoke all on function public.restore_group(uuid),public.delete_group(uuid) from public,anon;
grant execute on function public.restore_group(uuid),public.delete_group(uuid) to authenticated;

-- Deleted groups never reopen through accepted invitation links.
create or replace function public.accept_invitation(p_token text) returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid:=private.require_user(); inv public.group_invitations; verified boolean; mail text; begin
 select email_confirmed_at is not null, lower(email) into verified,mail from auth.users where id=u;
 if not coalesce(verified,false) then raise exception 'Verify your email before joining'; end if;
 select * into inv from public.group_invitations where token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex') for update;
 if inv.accepted_by=u and public.is_group_member(inv.group_id) then return inv.group_id;end if;
 if inv.id is null or inv.expires_at<=now() or inv.accepted_by is not null then raise exception 'Invalid, expired, or used invitation'; end if;
 if inv.email is not null and inv.email<>mail then raise exception 'Invitation belongs to another email' using errcode='42501'; end if;
 perform 1 from public.groups where id=inv.group_id and archived_at is null and deleted_at is null for update;
 if not found then raise exception 'Group is archived'; end if;
 if (select count(*) from public.group_members where group_id=inv.group_id and active)>=100 then raise exception 'Group member limit reached'; end if;
 if exists(select 1 from public.group_members where group_id=inv.group_id and user_id=u and active) then return inv.group_id;end if;
 insert into public.group_members(group_id,user_id) values(inv.group_id,u) on conflict(group_id,user_id) do update set active=true,role='member',billing_manager=false,left_at=null;
 update public.group_invitations set accepted_by=u,accepted_at=now() where id=inv.id; perform private.audit(inv.group_id,'member_joined',u); return inv.group_id;
end $$;


create or replace function public.invitation_preview(p_token text) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare inv public.group_invitations;result jsonb;existing boolean;begin
 if p_token !~ '^[a-f0-9]{64}$' then raise exception 'This invitation link is not valid'; end if;
 select * into inv from public.group_invitations where token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex');
 existing:=inv.id is not null and exists(select 1 from public.group_members m where m.group_id=inv.group_id and m.user_id=auth.uid() and m.active);
 if inv.id is null or ((inv.expires_at<=now() or inv.accepted_by is not null) and not(existing and (inv.accepted_by is null or inv.accepted_by=auth.uid()))) then raise exception 'This invitation has expired or has already been used'; end if;
 select jsonb_build_object('group_name',g.name,'inviter',p.display_name,'expires_at',inv.expires_at,'email_bound',inv.email is not null,'already_member',existing) into result from public.groups g join public.profiles p on p.id=inv.invited_by where g.id=inv.group_id and g.archived_at is null and g.deleted_at is null;
 if result is null then raise exception 'This group is no longer available'; end if;return result;
end $$;


-- 202611040001_early_access.sql
-- A server-controlled launch benefit, not a purchase or a fabricated store
-- entitlement. Turning this flag off later restores normal paid access rules.
insert into public.product_flags(key,enabled) values('group_plus_early_access',true)
on conflict(key) do update set enabled=excluded.enabled;

create function public.group_plus_early_access() returns boolean
language sql stable security definer set search_path='' as $$
 select auth.uid() is not null and coalesce((select enabled from public.product_flags where key='group_plus_early_access'),false)
$$;
revoke all on function public.group_plus_early_access() from public,anon;
grant execute on function public.group_plus_early_access() to authenticated;

create or replace function public.has_group_feature(p_user uuid,p_group uuid,p_feature text) returns boolean
language sql stable security definer set search_path='' as $$
 select p_user=auth.uid() and public.is_group_member(p_group)
 and p_feature in ('itemized','budgets','analytics','settlement_plan','recurring','reports','custom_rules')
 and (public.group_plus_early_access() or exists(select 1 from public.group_subscription_entitlements where group_id=p_group and status in('active','grace','cancelled') and expires_at>now()))
 and not exists(select 1 from public.group_feature_settings where group_id=p_group and feature_key=p_feature and not enabled)
$$;

-- Older clients must not begin a paid checkout while access is complimentary.
create or replace function public.begin_group_purchase(p_group uuid,p_product text) returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid:=private.require_user(); i uuid; begin
 perform private.require_open(p_group);
 if public.group_plus_early_access() then raise exception 'Group Plus is free during early access. No purchase is needed'; end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,1));
 if not exists(select 1 from public.group_members where group_id=p_group and user_id=u and active and billing_manager) then raise exception 'Billing manager role required' using errcode='42501'; end if;
 if exists(select 1 from public.billing_purchases where purchaser_id=u and group_id<>p_group) then raise exception 'Your store subscription is already assigned to another group'; end if;
 if exists(select 1 from public.group_subscription_entitlements where group_id=p_group and expires_at>now() and status in('active','grace','cancelled')) then raise exception 'This group already has an active subscription'; end if;
 if p_product not in('tracksy_group_monthly','tracksy_group_yearly') then raise exception 'Unknown product'; end if;
 update public.billing_purchase_intents set consumed_at=now() where purchaser_id=u and consumed_at is null and expires_at<=now();
 select id into i from public.billing_purchase_intents where purchaser_id=u and consumed_at is null and group_id=p_group and product_id=p_product;
 if i is not null then return i; end if;
 insert into public.billing_purchase_intents(purchaser_id,group_id,product_id) values(u,p_group,p_product) returning id into i;
 return i;
end $$;

commit;
